package com.banktagfolders;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(FolderTree.GROUP)
public interface BankTagFoldersConfig extends Config
{
	/**
	 * The tab background sprite is 40 pixels tall and is drawn tiled, so a taller
	 * row repeats it and shows the top edge of a second tab inside the first.
	 */
	int MAX_ROW_HEIGHT = 40;


	@ConfigItem(
		keyName = "tagRowHeight",
		name = "Tag row height",
		description = "Height of a row, folders included. 24 to 40, since the game's tab background is itself 40"
			+ " tall and repeats above that. Smaller fits more rows on screen.",
		position = 2
	)
	@Range(min = 24, max = MAX_ROW_HEIGHT)
	default int tagRowHeight()
	{
		return 40;
	}

	@ConfigItem(
		keyName = "tagTintStrength",
		name = "Tag tint strength",
		description = "How strongly a folder's colour tints the tag tabs inside it."
			+ " Zero leaves them looking like ordinary tabs.",
		position = 4
	)
	@Range(max = 100)
	default int tagTintStrength()
	{
		return 35;
	}

	@ConfigItem(
		keyName = "folderTintStrength",
		name = "Folder tint strength",
		description = "How strongly a folder's colour fills the folder's own row."
			+ " Zero leaves only the icon and the expand marker.",
		position = 5
	)
	@Range(max = 100)
	default int folderTintStrength()
	{
		return 68;
	}

	@ConfigItem(
		keyName = "protectLayoutSpacing",
		name = "Protect layout spacing",
		description = "Off by default, matching the Bank Tags plugin exactly: tagged items that are not in a tab's"
			+ " layout yet drop into the first free slots, from the top."
			+ "<br><br>Turn this on only if you deliberately leave blank slots as spacing and want them left alone --"
			+ " unlaid items are then appended below the layout instead. If your tabs rely on those items landing"
			+ " in the blanks, this will look wrong.",
		position = 6
	)
	default boolean protectLayoutSpacing()
	{
		// Deliberately matching core rather than "protecting" by default. A tab
		// whose blank slots are where its untracked items are *meant* to land
		// renders wrong the moment they are appended instead -- which is not a
		// trade to make on a player's behalf without them asking.
		return false;
	}
}

package com.banktagfolders;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetDrag;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.util.Text;

/**
 * Folders for bank tag tabs.
 * <p>
 * An add-on to the core Bank Tags plugin, which keeps drawing its tag column
 * exactly as it always has. After each of its rebuilds this plugin hides the
 * tabs inside closed folders, adds a header row per folder, and restacks the
 * rest. Tags, icons, layouts, import and export, renaming and deleting all stay
 * with Bank Tags, and nothing is ever written into its configuration.
 * <p>
 * Handlers that touch the column run at a low priority on purpose: core builds
 * and positions its tabs on the same events, and so do the layout plugins, so
 * waiting for all of them keeps this out of their way.
 */
@Slf4j
@PluginDescriptor(
	name = "Bank Tag Folders",
	description = "Group bank tag tabs into collapsible folders",
	tags = {"bank", "tag", "tags", "tab", "tabs", "folder", "folders", "organise", "organize"}
)
public class BankTagFoldersPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private EventBus eventBus;

	@Inject
	private FolderTree tree;

	@Inject
	private CoreBankTags core;

	@Inject
	private TagColumn column;

	@Inject
	private ColumnActions actions;

	@Inject
	private BankTagFoldersConfig config;

	@Inject
	private ChatMessageManager chatMessageManager;

	/** So the "turn the core strip on" nudge is said once, not every bank open. */
	private boolean warned;

	private DropRepair dropRepair;

	@Provides
	BankTagFoldersConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankTagFoldersConfig.class);
	}

	@Override
	protected void startUp()
	{
		dropRepair = new DropRepair(client, column);
		eventBus.register(dropRepair);

		clientThread.invoke(() ->
		{
			tree.load();
			warned = false;
			column.attach();
			// The bank may already be open when the plugin is enabled.
			if (ready() && client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER) != null)
			{
				column.rebuild();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		eventBus.unregister(dropRepair);
		clientThread.invoke(column::release);
	}

	/**
	 * Whether the core column is there to rearrange.
	 * <p>
	 * Deliberately not something we fix by writing to the core plugin's config:
	 * silently flipping another plugin's setting is the kind of surprise that is
	 * hard to attribute later.
	 */
	private boolean ready()
	{
		return core.isAvailable() && core.isCoreStripEnabled();
	}

	// ------------------------------------------------------------------
	// Bank lifecycle
	// ------------------------------------------------------------------

	@Subscribe(priority = -10)
	public void onScriptPreFired(ScriptPreFired event)
	{
		int id = event.getScriptId();

		if (id == ScriptID.BANKMAIN_INIT)
		{
			if (ready())
			{
				// Bank Tags reopens the last tag as the bank initialises; the
				// folder holding it is opened once the column has been drawn.
				column.requestReveal();
			}
			else
			{
				nudge();
			}
		}
		else if (id == ScriptID.BANKMAIN_FINISHBUILDING)
		{
			if (ready())
			{
				column.rebuild();
			}
		}
		else if (id == ScriptID.BANKMAIN_SIZE_CHECK && ready())
		{
			onSizeCheck();
		}
	}

	private void nudge()
	{
		if (warned || !core.isAvailable())
		{
			return;
		}

		warned = true;
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage("Bank Tag Folders is idle: turn on \"Tag tabs\" in the Bank Tags plugin "
				+ "and your folders will appear on its column.")
			.build());
	}

	/**
	 * Detect a bank resize the way core does: the script is about to resize the
	 * container, so the new size is compared against the current one and the
	 * layout is redone once it has been applied. Ours is queued after core's.
	 */
	private void onSizeCheck()
	{
		int[] stack = client.getIntStack();
		int size = client.getIntStackSize();
		if (size < 5)
		{
			return;
		}

		Widget widget = client.getWidget(stack[size - 5]);
		if (widget == null)
		{
			return;
		}

		if (widget.getWidth() != stack[size - 4] || widget.getHeight() != stack[size - 3])
		{
			clientThread.invokeLater(column::layoutRows);
		}
	}

	// The storage popup covers part of the column, so core repacks its rows into
	// the height that is left and we repack ours into the same space.
	@Subscribe(priority = -10)
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.BANKMAIN_POPUP_TAB_DRAW)
		{
			column.layoutRows();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN && event.isUnload())
		{
			column.onBankClosed();
		}
	}

	/**
	 * Core rebuilds its tabs from inside its own option handlers (delete, rename,
	 * import) and none of them raises an event. Noticing the new widgets here is
	 * what puts the folders back.
	 */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		column.heal();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (BankTagsPlugin.CONFIG_GROUP.equals(event.getGroup()))
		{
			if (BankTagsPlugin.TAG_TABS_CONFIG.equals(event.getKey()))
			{
				followRename(csv(event.getOldValue()), csv(event.getNewValue()));
			}
			else if ("useTabs".equals(event.getKey()))
			{
				warned = false;
			}
			return;
		}

		// Only settings, never our own stored structure. reconcile() saves the
		// folder tree during a draw, and reacting to that would schedule another
		// draw, which reconciles, which saves.
		if (FolderTree.GROUP.equals(event.getGroup())
			&& !FolderTree.KEY_FOLDERS.equals(event.getKey())
			&& !FolderTree.KEY_ROOTS.equals(event.getKey()))
		{
			clientThread.invokeLater(column::rebuild);
		}
	}

	/**
	 * Carry a renamed tab's place in its folder across. Without this the old name
	 * would read as deleted and the new one as new, and a renamed tab would drop
	 * out of its folder to the bottom of the column. Done here, as core writes
	 * the list, so it is settled before the column is drawn again.
	 */
	private void followRename(List<String> before, List<String> after)
	{
		String[] renamed = FolderTree.renamed(before, after);
		if (renamed != null)
		{
			tree.renameTag(renamed[0], renamed[1]);
		}
	}

	private static List<String> csv(@Nullable String value)
	{
		if (value == null || value.isEmpty())
		{
			return new ArrayList<>();
		}
		return new ArrayList<>(Text.fromCSV(value));
	}

	// ------------------------------------------------------------------
	// Menu
	// ------------------------------------------------------------------

	/**
	 * Clicks on the two options this plugin adds to core's widgets, and, when
	 * asked for, the tab click itself. Consumed so core's listener, which has no
	 * idea what they mean, is never run for them.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		Widget widget = event.getWidget();
		if (widget == null || !column.isDrawn())
		{
			return;
		}

		String option = event.getMenuOption();
		if (TagColumn.OPTION_NEW_FOLDER.equals(option) && column.isNewTab(widget))
		{
			event.consume();
			actions.newFolder();
			return;
		}

		StripRow row = column.rowFor(widget);
		if (row == null || !row.isTag())
		{
			return;
		}

		if (TagColumn.OPTION_UNFILE.equals(option))
		{
			event.consume();
			actions.unfile(row);
		}
		else if (TagColumn.OPTION_VIEW_TAG.equals(option) && config.protectLayoutSpacing())
		{
			event.consume();
			actions.openTag(row.getTag());
		}
	}

	// ------------------------------------------------------------------
	// Dragging
	// ------------------------------------------------------------------

	/**
	 * Runs before core, because core's handling of a drop onto the column would
	 * do the wrong thing with our rows. Nulling the drop target is how core
	 * cancels a drop itself for its "prevent tag tab drags" option.
	 * <p>
	 * <ul>
	 * <li>A tab or folder being carried: core would swap tabs by name, which
	 * scrambles a folder's order, so the drop is taken off it and handled here.</li>
	 * <li>Anything dropped on a folder row: core would read a bank item as "tag
	 * this item with the folder's name" and create a tag nobody asked for.</li>
	 * <li>Anything held over a scroll arrow: core's scrolling counts flat tabs,
	 * ours counts rows.</li>
	 * </ul>
	 * Every other drop is left alone, so tagging an item by dropping it on a tab
	 * works exactly as it does without this plugin.
	 */
	@Subscribe(priority = 100)
	public void onWidgetDrag(WidgetDrag event)
	{
		if (!column.isDrawn())
		{
			return;
		}

		Widget dragged = client.getDraggedWidget();
		if (dragged == null)
		{
			return;
		}

		Widget target = client.getDraggedOnWidget();
		boolean released = client.getMouseCurrentButton() == 0;
		int arrow = column.arrowDirection(target);
		StripRow source = column.rowFor(dragged);

		if (source == null && (target == null || !(column.isOurs(target) || arrow != 0)))
		{
			return;
		}

		client.setDraggedOnWidget(null);

		if (!released)
		{
			if (arrow != 0)
			{
				column.scrollTick(arrow);
			}
			return;
		}

		if (source == null)
		{
			return;
		}

		try
		{
			handleDrop(source);
		}
		catch (Exception e)
		{
			log.warn("Tag column drop failed", e);
		}
	}

	/**
	 * Draw the column again once core has finished with a drop.
	 * <p>
	 * Core rebuilds its tabs on release for every drop it does not otherwise
	 * handle, moving a bank item included, and that rebuild takes our changes
	 * with it. Leaving it to the next tick shows a frame of the flat column.
	 * <p>
	 * A separate object because the event bus requires a subscriber to be named
	 * after its event, so one class cannot subscribe to {@code WidgetDrag} twice,
	 * and the handler above has to stay ahead of core.
	 */
	static class DropRepair
	{
		private final Client client;
		private final TagColumn column;

		DropRepair(Client client, TagColumn column)
		{
			this.client = client;
			this.column = column;
		}

		@Subscribe(priority = -100)
		public void onWidgetDrag(WidgetDrag event)
		{
			if (client.getMouseCurrentButton() == 0)
			{
				column.heal();
			}
		}
	}

	private void handleDrop(StripRow source)
	{
		TagColumn.Drop drop = column.dropAt(client.getMouseCanvasPosition());
		if (drop == null)
		{
			// Released inside the column but past the last row: send it to the
			// bottom of the top level. Released outside: just tidy up.
			if (column.containsCanvasPoint(client.getMouseCanvasPosition()))
			{
				if (source.isTag())
				{
					tree.moveToRoot(source.getTag(), -1);
				}
				else
				{
					tree.reorderRoot(tree.rootKey(source), -1);
				}
			}
			column.rebuild();
			return;
		}

		if (source.isTag())
		{
			dropTag(source, drop);
		}
		else
		{
			dropFolder(source, drop);
		}
	}

	private void dropTag(StripRow source, TagColumn.Drop drop)
	{
		String tag = source.getTag();
		StripRow target = drop.getRow();
		TagColumn.DropZone zone = drop.getZone();

		if (target.sameAs(source))
		{
			column.rebuild();
			return;
		}

		if (target.isFolder())
		{
			Folder folder = target.getFolder();
			if (zone == TagColumn.DropZone.INTO)
			{
				tree.moveIntoFolder(tag, folder.getId(), -1);
				// Expanding shows the tag landing where it was put, instead of
				// it seeming to vanish into a closed folder.
				if (folder.isCollapsed())
				{
					tree.toggleCollapsed(folder.getId());
				}
			}
			else if (zone == TagColumn.DropZone.BEFORE)
			{
				tree.moveTagNear(tag, target, false);
			}
			else if (folder.isCollapsed())
			{
				tree.moveTagNear(tag, target, true);
			}
			else
			{
				// Just below an open folder's header reads as "first one inside".
				tree.moveIntoFolder(tag, folder.getId(), 0);
			}

			column.rebuild();
			return;
		}

		Folder targetFolder = target.getParent();

		if (zone == TagColumn.DropZone.INTO)
		{
			if (targetFolder != null)
			{
				tree.moveTagIntoFolderNear(tag, targetFolder.getId(), target.getTag(), true);
				column.rebuild();
			}
			else
			{
				// Two loose tabs dropped together: the phone-homescreen gesture.
				// The tabs only move once the folder has been named, so backing
				// out of the prompt leaves the column as it was.
				actions.createFolderFrom(target.getTag(), tag);
				column.rebuild();
			}
			return;
		}

		boolean after = zone == TagColumn.DropZone.AFTER;
		if (targetFolder != null)
		{
			tree.moveTagIntoFolderNear(tag, targetFolder.getId(), target.getTag(), after);
		}
		else
		{
			tree.moveTagNear(tag, target, after);
		}
		column.rebuild();
	}

	private void dropFolder(StripRow source, TagColumn.Drop drop)
	{
		StripRow target = drop.getRow();
		Folder folder = source.getFolder();

		// Dropping a folder onto its own contents would ask it to reorder
		// relative to itself.
		if (target.sameAs(source)
			|| (target.getParent() != null && target.getParent().getId().equals(folder.getId())))
		{
			column.rebuild();
			return;
		}

		// Folders reorder only. Nesting one inside another has no way to be
		// drawn, so a drop into the middle of a row is treated as "after it".
		tree.moveFolderNear(folder.getId(), target, drop.getZone() != TagColumn.DropZone.BEFORE);
		column.rebuild();
	}
}

package com.banktagfolders;

import java.util.function.Consumer;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Provider;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.SoundEffectID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.game.chatbox.ChatboxItemSearch;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.plugins.banktags.tabs.TabInterface;

/**
 * The options this plugin adds: everything on a folder, plus the two additions
 * to a tab and to the new-tab button. Every other tab option is core's.
 */
@Slf4j
@Singleton
public class ColumnActions
{
	/**
	 * The bank tab varbit value meaning "potion store". Core reads this from
	 * {@code PotionStorage}, whose constant is package-private, so it is
	 * restated here.
	 */
	private static final int BANKTAB_POTIONSTORE = 15;

	private final Client client;
	private final ClientThread clientThread;
	private final FolderTree tree;
	private final CoreBankTags core;
	private final ChatboxPanelManager chatboxPanelManager;
	private final Provider<ChatboxItemSearch> itemSearch;
	private final ChatMessageManager chatMessageManager;
	private final Provider<TagColumn> column;

	@Inject
	ColumnActions(Client client, ClientThread clientThread, FolderTree tree, CoreBankTags core,
		ChatboxPanelManager chatboxPanelManager, Provider<ChatboxItemSearch> itemSearch,
		ChatMessageManager chatMessageManager, Provider<TagColumn> column)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.tree = tree;
		this.core = core;
		this.chatboxPanelManager = chatboxPanelManager;
		this.itemSearch = itemSearch;
		this.chatMessageManager = chatMessageManager;
		this.column = column;
	}

	// ------------------------------------------------------------------
	// Tab options
	// ------------------------------------------------------------------

	/**
	 * Open or close a tag, for when the layout spacing option is on and core's
	 * own click has been held back. Mirrors what core's "View tag tab" does.
	 */
	void openTag(String tag)
	{
		if (isPotionStoreOpen())
		{
			// The potion store is a bank tab on the server, not just a client view,
			// so moving off it client-side would leave deposits going to it. We
			// cannot close it without sending an action, so we decline instead.
			say("Close the potion store before opening a tag tab.");
			return;
		}
		client.setVarbit(VarbitID.BANK_CURRENTTAB, 0);

		if (tag.equals(core.activeTag()))
		{
			core.closeTag();
			core.resetBank();
		}
		else
		{
			core.openTag(tag);
		}

		client.playSoundEffect(SoundEffectID.UI_BOOP);
	}

	void unfile(StripRow row)
	{
		Folder folder = row.getParent();
		if (folder == null)
		{
			return;
		}

		// Lands directly under the folder it came out of, which is where the
		// eye is already looking.
		int at = tree.rootIndexOf(StripRow.folder(folder));
		tree.moveToRoot(row.getTag(), at < 0 ? -1 : at + 1);
		column.get().rebuild();
	}

	// ------------------------------------------------------------------
	// Folder options
	// ------------------------------------------------------------------

	void onFolderOp(int op, StripRow row)
	{
		Folder folder = row.getFolder();
		try
		{
			switch (op)
			{
				case TagColumn.FOLDER_OP_TOGGLE:
					tree.toggleCollapsed(folder.getId());
					column.get().rebuild();
					break;

				case TagColumn.FOLDER_OP_CHANGE_ICON:
					itemSearch.get()
						.tooltipText("Change icon (" + folder.getName() + ")")
						.onItemSelected(itemId -> clientThread.invokeLater(() ->
						{
							tree.setIcon(folder.getId(), itemId);
							column.get().rebuild();
						}))
						.build();
					break;

				case TagColumn.FOLDER_OP_SET_COLOUR:
					setFolderColour(folder);
					break;

				case TagColumn.FOLDER_OP_RENAME:
					promptName("Enter new name for folder \"" + folder.getName() + "\":", name ->
					{
						tree.rename(folder.getId(), name);
						column.get().rebuild();
					});
					break;

				case TagColumn.FOLDER_OP_DELETE:
					// Only the grouping goes; the tabs inside spill back out
					// where the folder stood. Nothing here can lose a tag.
					tree.dissolve(folder.getId());
					column.get().rebuild();
					break;

				default:
					break;
			}
		}
		catch (Exception e)
		{
			log.warn("Folder option {} failed", op, e);
		}
	}

	/**
	 * Ask for a colour as hex. There is no colour picker reachable from the
	 * bank, and the chatbox is already how this plugin asks for names.
	 */
	private void setFolderColour(Folder folder)
	{
		chatboxPanelManager.openTextInput("Folder colour as hex (e.g. 3a6b8b):")
			.addCharValidator(TabInterface.FILTERED_CHARS)
			.onDone((Consumer<String>) value -> clientThread.invoke(() ->
			{
				Integer rgb = parseHexColour(value);
				if (rgb == null)
				{
					say("That is not a hex colour. Try six hex digits, like 3a6b8b.");
					return;
				}
				tree.setColor(folder.getId(), rgb);
				column.get().rebuild();
			}))
			.build();
	}

	/** Accepts rgb or rrggbb, with or without a leading hash. */
	@Nullable
	static Integer parseHexColour(@Nullable String value)
	{
		String hex = value == null ? "" : value.trim().replace("#", "");
		if (hex.length() == 3)
		{
			StringBuilder expanded = new StringBuilder();
			for (char c : hex.toCharArray())
			{
				expanded.append(c).append(c);
			}
			hex = expanded.toString();
		}

		if (hex.length() != 6)
		{
			return null;
		}

		try
		{
			return Integer.parseInt(hex, 16);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** Two tabs dragged together become a folder, once it has a name. */
	void createFolderFrom(String target, String dragged)
	{
		promptName("Name the new folder:", name ->
		{
			tree.createFolder(name, target, dragged);
			column.get().rebuild();
		});
	}

	/** An empty folder from the new-tab button, to be filled by dragging. */
	void newFolder()
	{
		promptName("Folder name:", name ->
		{
			tree.createEmptyFolder(name);
			column.get().rebuild();
		});
	}

	// ------------------------------------------------------------------
	// Helpers
	// ------------------------------------------------------------------

	private void promptName(String prompt, Consumer<String> onDone)
	{
		chatboxPanelManager.openTextInput(prompt)
			.addCharValidator(TabInterface.FILTERED_CHARS)
			.onDone((Consumer<String>) value ->
			{
				String name = value.trim();
				if (!name.isEmpty())
				{
					// Chatbox input is driven from key events, so the callback is
					// not guaranteed to be on the client thread, and every one of
					// these handlers goes on to rebuild widgets.
					clientThread.invoke(() -> onDone.accept(name));
				}
			})
			.build();
	}

	private boolean isPotionStoreOpen()
	{
		return client.getVarbitValue(VarbitID.BANK_CURRENTTAB) == BANKTAB_POTIONSTORE;
	}

	void say(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(message)
			.build());
	}
}

package com.banktagfolders;

import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.bank.BankSearch;
import net.runelite.client.plugins.banktags.BankTagsConfig;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.util.Text;

/**
 * What this plugin needs to ask of the core Bank Tags plugin.
 * <p>
 * Bank Tags draws the tag column, owns the tags, icons and layouts, and does
 * everything a tab's menu offers. This plugin only rearranges the column once
 * it has been drawn, so the list of things it asks for is short: which tabs
 * exist, which one is open, and how to open or close one.
 * <p>
 * Nothing here is injectable the ordinary way. {@code BankTagsService} is an
 * interface with no binding a side-loaded plugin's child injector can see, so it
 * is found among the loaded plugins, and every accessor degrades rather than
 * throwing.
 */
@Slf4j
@Singleton
public class CoreBankTags
{
	private final PluginManager pluginManager;
	private final ConfigManager configManager;
	private final BankTagFoldersConfig config;

	@Nullable
	private BankTagsService service;

	@Nullable
	private BankSearch bankSearch;

	@Inject
	CoreBankTags(PluginManager pluginManager, ConfigManager configManager, BankTagFoldersConfig config)
	{
		this.pluginManager = pluginManager;
		this.configManager = configManager;
		this.config = config;
	}

	/**
	 * The core plugin, found among the loaded plugins because it implements the
	 * service interface itself.
	 */
	@Nullable
	private BankTagsService service()
	{
		if (service == null)
		{
			for (Plugin plugin : pluginManager.getPlugins())
			{
				if (plugin instanceof BankTagsService)
				{
					service = (BankTagsService) plugin;
					break;
				}
			}
		}
		return service;
	}

	/**
	 * Resolve one of the core plugin's collaborators from the Bank Tags plugin's
	 * own injector, which is where they are bound. The root injector has no
	 * binding for the ones that depend on the plugin itself.
	 */
	@Nullable
	private <T> T resolve(Class<T> type)
	{
		BankTagsService bankTags = service();
		if (bankTags instanceof Plugin)
		{
			try
			{
				return ((Plugin) bankTags).getInjector().getInstance(type);
			}
			catch (Exception e)
			{
				log.debug("Could not resolve {} from the Bank Tags injector", type.getSimpleName(), e);
			}
		}

		try
		{
			return RuneLite.getInjector().getInstance(type);
		}
		catch (Exception e)
		{
			log.warn("Could not resolve {}", type.getSimpleName(), e);
			return null;
		}
	}

	@Nullable
	private BankSearch bankSearch()
	{
		if (bankSearch == null)
		{
			bankSearch = resolve(BankSearch.class);
		}
		return bankSearch;
	}

	boolean isAvailable()
	{
		return service() != null;
	}

	/**
	 * Whether the core plugin is drawing its tag column. Folders have nothing to
	 * rearrange without it, so this plugin waits until it is on.
	 */
	boolean isCoreStripEnabled()
	{
		BankTagsConfig bankTagsConfig = configManager.getConfig(BankTagsConfig.class);
		// The core default is on, so an unreadable proxy counts as on too.
		return bankTagsConfig == null || bankTagsConfig.tabs();
	}

	/** Tag names, in the order the core plugin stores them. */
	List<String> tagTabs()
	{
		String csv = configManager.getConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG);
		if (csv == null || csv.isEmpty())
		{
			return new ArrayList<>();
		}
		return new ArrayList<>(Text.fromCSV(csv));
	}

	@Nullable
	String activeTag()
	{
		BankTagsService bankTags = service();
		return bankTags == null ? null : bankTags.getActiveTag();
	}

	/**
	 * Open a tag the way the core column does, but with the option to leave
	 * layout spacing alone. Only used when that option is on: every other tab
	 * click is left to the core plugin.
	 */
	void openTag(String tag)
	{
		BankTagsService bankTags = service();
		if (bankTags == null)
		{
			return;
		}

		int options = BankTagsService.OPTION_ALLOW_MODIFICATIONS;
		if (config.protectLayoutSpacing())
		{
			// Without this, a tagged item that is not in the tab's layout yet is
			// dropped into the first free slot, from the very top, and the layout
			// is saved. Blank slots left as deliberate spacing get eaten. This
			// appends such items after the last one instead.
			options |= BankTagsService.OPTION_ITEMS_NOT_IN_LAYOUT_AT_BOTTOM;
		}

		bankTags.openBankTag(tag, options);
	}

	void closeTag()
	{
		BankTagsService bankTags = service();
		if (bankTags != null)
		{
			bankTags.closeBankTag();
		}
	}

	void resetBank()
	{
		BankSearch search = bankSearch();
		if (search != null)
		{
			search.reset(true);
		}
	}
}

package com.banktagfolders;

import java.util.ArrayList;
import java.util.List;
import lombok.Data;

/**
 * A named, collapsible group of bank tags.
 * <p>
 * Folders live entirely in this plugin's own config group. Nothing about them
 * is written back into {@code banktags}, so turning this plugin off leaves the
 * player with exactly the flat tag list they had before -- no orphaned
 * pseudo-tabs, no reordering, nothing to clean up.
 */
@Data
public class Folder
{
	/**
	 * Stable identity, generated once at creation.
	 * <p>
	 * Deliberately not the folder's name: renaming has to be a pure relabel, and
	 * keying on the name would orphan every row pointing at the old one.
	 */
	private String id;

	private String name;

	/**
	 * Item sprite drawn on the folder row. Zero means "borrow the icon of the
	 * first tag inside", which keeps a freshly dragged-together folder from
	 * showing up blank before the player has picked anything.
	 */
	private int iconItemId;

	private boolean collapsed;

	/**
	 * Row colour as 0xRRGGBB, shared with every tag inside the folder.
	 * <p>
	 * Colour is what marks membership, rather than indenting the member rows.
	 * The column is only 39px wide and an item sprite is 36 of them, so an
	 * indent large enough to notice also pushed the icon off the edge.
	 * <p>
	 * Zero means one has not been chosen, and a palette colour is assigned.
	 */
	private int color;

	/** Member tags, in display order. */
	private List<String> tags = new ArrayList<>();
}

package com.banktagfolders;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ThreadLocalRandom;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * The folder structure laid over the core plugin's flat tag list, plus its
 * persistence.
 * <p>
 * The core tag list stays the single source of truth for which tags exist; this
 * class only records how they are <em>grouped</em>. That split is what makes the
 * plugin non-destructive: every mutation here writes to
 * {@value #GROUP}, never to {@code banktags}.
 */
@Slf4j
@Singleton
public class FolderTree
{
	static final String GROUP = "banktagfolders";

	static final String KEY_FOLDERS = "folders";
	static final String KEY_ROOTS = "roots";

	/** Root entries are tagged so a folder id can never be read as a tag name. */
	private static final String TAG = "t:";
	private static final String FOLDER = "f:";

	/**
	 * Default folder colours, mid-dark so the game's white and orange text stays
	 * readable on top. A new folder takes the first one not already in use.
	 */
	private static final int[] PALETTE = {
		0x3A6B8B, 0x4A7A4A, 0x8B3A3A, 0x6B4A8B,
		0x8B7A3A, 0x3A8B7A, 0x8B5A3A, 0x7A3A6B,
	};

	private final ConfigManager configManager;

	/**
	 * The client's Gson, injected rather than constructed. Building a fresh
	 * instance is rejected by the Plugin Hub, and it would also mean this
	 * plugin quietly stops matching the client's own serialisation settings if
	 * those ever change.
	 * <p>
	 * Everything is read and written as a concrete array type rather than via
	 * Gson's {@code TypeToken}. TypeToken resolves a generic type at runtime
	 * through {@code java.lang.reflect.Type}, and the Plugin Hub does not permit
	 * reflection; an array carries its element type in the class itself.
	 */
	private final Gson gson;

	/** Folder id to folder, insertion ordered so saves round-trip stably. */
	private final Map<String, Folder> folders = new LinkedHashMap<>();

	/** Top level in display order; each entry is {@code t:<tag>} or {@code f:<id>}. */
	private final List<String> roots = new ArrayList<>();

	@Inject
	FolderTree(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	// ------------------------------------------------------------------
	// Persistence
	// ------------------------------------------------------------------

	void load()
	{
		folders.clear();
		roots.clear();

		Folder[] stored = read(KEY_FOLDERS, Folder[].class);
		if (stored != null)
		{
			for (Folder folder : stored)
			{
				// A null id would make the folder unaddressable and every row
				// pointing at it dead, so drop it rather than render a ghost.
				if (folder != null && folder.getId() != null)
				{
					if (folder.getTags() == null)
					{
						folder.setTags(new ArrayList<>());
					}
					if (folder.getColor() == 0)
					{
						folder.setColor(nextColor());
					}
					folders.put(folder.getId(), folder);
				}
			}
		}

		String[] storedRoots = read(KEY_ROOTS, String[].class);
		if (storedRoots != null)
		{
			Collections.addAll(roots, storedRoots);
		}
	}

	@Nullable
	private <T> T read(String key, Class<T> type)
	{
		String json = configManager.getConfiguration(GROUP, key);
		if (json == null || json.isEmpty())
		{
			return null;
		}
		try
		{
			return gson.fromJson(json, type);
		}
		catch (JsonSyntaxException e)
		{
			// Better to start from an empty structure than to refuse to render
			// the column at all; reconcile() will rebuild it from the live tags.
			log.warn("Discarding unreadable {}.{}", GROUP, key, e);
			return null;
		}
	}

	void save()
	{
		configManager.setConfiguration(GROUP, KEY_FOLDERS, gson.toJson(folders.values().toArray(new Folder[0])));
		configManager.setConfiguration(GROUP, KEY_ROOTS, gson.toJson(roots.toArray(new String[0])));
	}

	// ------------------------------------------------------------------
	// Reconciliation against the core tag list
	// ------------------------------------------------------------------

	/**
	 * Fold the live tag list into the stored structure.
	 * <p>
	 * Runs before every render, because tags can appear and disappear entirely
	 * outside this plugin -- created from the core plugin's own UI, deleted,
	 * renamed, or imported. Anything unknown is adopted at the end of the
	 * column and anything stale is dropped, so the two never drift apart.
	 *
	 * @param liveTags tag names in the order {@code banktags} lists them
	 */
	void reconcile(List<String> liveTags)
	{
		Set<String> live = new LinkedHashSet<>(liveTags);
		boolean dirty = false;

		for (Folder folder : new ArrayList<>(folders.values()))
		{
			boolean lostTags = folder.getTags().retainAll(live);
			if (lostTags)
			{
				dirty = true;
			}

			// "Remove all from a folder to remove the folder", covering the case
			// where the last member was deleted from the bank rather than
			// dragged out. Conditioned on having actually lost something this
			// pass: an empty folder that did not just lose its last tag is a
			// brand new one waiting to be filled, and deleting it here would
			// make "New folder" appear to do nothing.
			if (lostTags && folder.getTags().isEmpty())
			{
				folders.remove(folder.getId());
				dirty = true;
			}
		}

		Set<String> filed = new HashSet<>();
		for (Folder folder : folders.values())
		{
			filed.addAll(folder.getTags());
		}

		Set<String> seen = new HashSet<>();
		for (Iterator<String> it = roots.iterator(); it.hasNext(); )
		{
			String entry = it.next();
			if (!seen.add(entry) || !isLiveRoot(entry, live, filed))
			{
				it.remove();
				dirty = true;
			}
		}

		// Folders and tags the roots list has never seen join the bottom of the
		// column, tags in the order the bank itself lists them.
		for (Folder folder : folders.values())
		{
			if (!roots.contains(FOLDER + folder.getId()))
			{
				roots.add(FOLDER + folder.getId());
				dirty = true;
			}
		}
		for (String tag : liveTags)
		{
			if (!filed.contains(tag) && !roots.contains(TAG + tag))
			{
				roots.add(TAG + tag);
				dirty = true;
			}
		}

		if (dirty)
		{
			save();
		}
	}

	private boolean isLiveRoot(String entry, Set<String> live, Set<String> filed)
	{
		if (entry.startsWith(FOLDER))
		{
			return folders.containsKey(entry.substring(FOLDER.length()));
		}
		if (entry.startsWith(TAG))
		{
			String tag = entry.substring(TAG.length());
			// A tag that has since been filed into a folder must not also keep
			// its top-level slot, or it renders twice.
			return live.contains(tag) && !filed.contains(tag);
		}
		return false;
	}

	/**
	 * The one tab that changed name between two tab lists, as {from, to}, or null
	 * when the change was anything else.
	 * <p>
	 * Core renames by removing the old name and adding the new one in a single
	 * write, so exactly one name gone and one arrived is a rename. Anything else
	 * (a deletion, an import, a new tab) is not, and reconcile() deals with it.
	 */
	@Nullable
	static String[] renamed(List<String> before, List<String> after)
	{
		List<String> gone = new ArrayList<>(before);
		gone.removeAll(after);
		List<String> arrived = new ArrayList<>(after);
		arrived.removeAll(before);

		if (gone.size() == 1 && arrived.size() == 1)
		{
			return new String[]{gone.get(0), arrived.get(0)};
		}
		return null;
	}

	// ------------------------------------------------------------------
	// Display
	// ------------------------------------------------------------------

	/** The column, flattened: folder headers with their members under them. */
	List<StripRow> rows()
	{
		List<StripRow> rows = new ArrayList<>();
		for (String entry : roots)
		{
			if (entry.startsWith(TAG))
			{
				rows.add(StripRow.tag(entry.substring(TAG.length()), null));
				continue;
			}

			Folder folder = folders.get(entry.substring(FOLDER.length()));
			if (folder == null)
			{
				continue;
			}

			rows.add(StripRow.folder(folder));
			if (!folder.isCollapsed())
			{
				for (String tag : folder.getTags())
				{
					rows.add(StripRow.tag(tag, folder));
				}
			}
		}
		return rows;
	}

	@Nullable
	Folder folder(String id)
	{
		return folders.get(id);
	}

	@Nullable
	Folder folderOf(String tag)
	{
		for (Folder folder : folders.values())
		{
			if (folder.getTags().contains(tag))
			{
				return folder;
			}
		}
		return null;
	}

	// ------------------------------------------------------------------
	// Mutations
	// ------------------------------------------------------------------

	/**
	 * Drag one tab onto another: the phone-homescreen gesture that makes a
	 * folder. The new folder takes the slot the target tab was occupying, so it
	 * appears exactly where the player dropped it.
	 */
	Folder createFolder(String name, String target, String dragged)
	{
		Folder folder = new Folder();
		folder.setId(newId());
		folder.setName(name);
		folder.setColor(nextColor());
		folder.getTags().add(target);
		folder.getTags().add(dragged);

		// Detach the dragged tag first, then re-read the target's index: taking
		// the index up front and detaching afterwards drops the folder a slot
		// too high whenever the dragged tab sat above its target.
		detach(dragged);
		int at = roots.indexOf(TAG + target);
		detach(target);

		folders.put(folder.getId(), folder);
		roots.add(at < 0 || at > roots.size() ? roots.size() : at, FOLDER + folder.getId());
		save();
		return folder;
	}

	/** An empty folder, added at the bottom, for filling by drag afterwards. */
	Folder createEmptyFolder(String name)
	{
		Folder folder = new Folder();
		folder.setId(newId());
		folder.setName(name);
		folder.setColor(nextColor());
		folders.put(folder.getId(), folder);
		roots.add(FOLDER + folder.getId());
		save();
		return folder;
	}

	/**
	 * Follow a tag through a rename, keeping its slot.
	 * <p>
	 * Without this, {@link #reconcile} would see the old name vanish and the new
	 * one appear, and quietly drop a renamed tab out of its folder to the bottom
	 * of the column.
	 */
	void renameTag(String from, String to)
	{
		int at = roots.indexOf(TAG + from);
		if (at >= 0)
		{
			roots.set(at, TAG + to);
		}

		for (Folder folder : folders.values())
		{
			int index = folder.getTags().indexOf(from);
			if (index >= 0)
			{
				folder.getTags().set(index, to);
			}
		}
		save();
	}

	/**
	 * The top-level slot a row occupies.
	 * <p>
	 * A tag inside a folder resolves to the folder's slot, so dropping next to
	 * a nested tab means "next to its folder" rather than nothing at all.
	 */
	private int rootSlotOf(StripRow target)
	{
		if (target.isFolder())
		{
			return roots.indexOf(FOLDER + target.getFolder().getId());
		}

		Folder parent = target.getParent();
		if (parent != null)
		{
			return roots.indexOf(FOLDER + parent.getId());
		}
		return roots.indexOf(TAG + target.getTag());
	}

	/** Drop a tag at the top level, immediately before or after a row. */
	void moveTagNear(String tag, StripRow target, boolean after)
	{
		detach(tag);

		// Resolved after detaching: removing the tag can shift every slot below
		// it, and can delete a folder it just emptied.
		int at = rootSlotOf(target);
		roots.add(at < 0 ? roots.size() : (after ? Math.min(at + 1, roots.size()) : at), TAG + tag);
		save();
	}

	/** Move a whole folder before or after a row. */
	void moveFolderNear(String folderId, StripRow target, boolean after)
	{
		String key = FOLDER + folderId;
		if (!roots.remove(key))
		{
			return;
		}

		int at = rootSlotOf(target);
		roots.add(at < 0 ? roots.size() : (after ? Math.min(at + 1, roots.size()) : at), key);
		save();
	}

	/** Drop a tag inside a folder, beside one of its existing members. */
	void moveTagIntoFolderNear(String tag, String folderId, String targetTag, boolean after)
	{
		detach(tag);

		Folder folder = folders.get(folderId);
		if (folder == null)
		{
			// detach() deletes a folder it just emptied, so the destination can
			// vanish underneath us when the tag was its only member.
			return;
		}

		List<String> tags = folder.getTags();
		int at = tags.indexOf(targetTag);
		tags.add(at < 0 ? tags.size() : (after ? Math.min(at + 1, tags.size()) : at), tag);
		save();
	}

	/** Nudge a top-level entry one slot up or down. */
	void moveRoot(String entry, int delta)
	{
		int from = roots.indexOf(entry);
		if (from < 0)
		{
			return;
		}

		int to = from + delta;
		if (to < 0 || to >= roots.size())
		{
			return;
		}

		roots.remove(from);
		roots.add(to, entry);
		save();
	}

	/** Nudge a tag one slot up or down within the folder holding it. */
	void moveWithinFolder(String tag, String folderId, int delta)
	{
		Folder folder = folders.get(folderId);
		if (folder == null)
		{
			return;
		}

		List<String> tags = folder.getTags();
		int from = tags.indexOf(tag);
		int to = from + delta;
		if (from < 0 || to < 0 || to >= tags.size())
		{
			return;
		}

		tags.remove(from);
		tags.add(to, tag);
		save();
	}

	/** Drop a tag into a folder, at {@code index} among its members, or last. */
	void moveIntoFolder(String tag, String folderId, int index)
	{
		Folder folder = folders.get(folderId);
		if (folder == null)
		{
			return;
		}

		detach(tag);

		// detach() deletes a folder it just emptied, so the destination may have
		// vanished underneath us when the tag was that folder's only member.
		if (!folders.containsKey(folderId))
		{
			return;
		}

		List<String> tags = folder.getTags();
		tags.add(index < 0 || index > tags.size() ? tags.size() : index, tag);
		save();
	}

	/** Drag a tag back out to the top level, landing at {@code index}. */
	void moveToRoot(String tag, int index)
	{
		detach(tag);
		roots.add(index < 0 || index > roots.size() ? roots.size() : index, TAG + tag);
		save();
	}

	/** Reorder a top-level entry (a loose tag, or a whole folder). */
	void reorderRoot(String entry, int index)
	{
		int from = roots.indexOf(entry);
		if (from < 0)
		{
			return;
		}
		roots.remove(from);
		roots.add(index < 0 || index > roots.size() ? roots.size() : index, entry);
		save();
	}

	/**
	 * Open whatever folder a tag is hiding in.
	 * <p>
	 * Used when the bank reopens on a remembered tag: leaving it inside a
	 * collapsed folder would show the tag's contents with nothing in the column
	 * marked active, which reads as a bug.
	 */
	void reveal(String tag)
	{
		Folder folder = folderOf(tag);
		if (folder != null && folder.isCollapsed())
		{
			folder.setCollapsed(false);
			save();
		}
	}

	/** The first palette colour no folder is using, else one by position. */
	private int nextColor()
	{
		for (int candidate : PALETTE)
		{
			boolean taken = false;
			for (Folder folder : folders.values())
			{
				if (folder.getColor() == candidate)
				{
					taken = true;
					break;
				}
			}
			if (!taken)
			{
				return candidate;
			}
		}
		return PALETTE[folders.size() % PALETTE.length];
	}

	void setColor(String folderId, int rgb)
	{
		Folder folder = folders.get(folderId);
		if (folder != null)
		{
			folder.setColor(rgb);
			save();
		}
	}

	void toggleCollapsed(String folderId)
	{
		Folder folder = folders.get(folderId);
		if (folder != null)
		{
			folder.setCollapsed(!folder.isCollapsed());
			save();
		}
	}

	void rename(String folderId, String name)
	{
		Folder folder = folders.get(folderId);
		if (folder != null)
		{
			folder.setName(name);
			save();
		}
	}

	void setIcon(String folderId, int itemId)
	{
		Folder folder = folders.get(folderId);
		if (folder != null)
		{
			folder.setIconItemId(itemId);
			save();
		}
	}

	/** Delete a folder, spilling its tags back out where it stood. */
	void dissolve(String folderId)
	{
		Folder folder = folders.remove(folderId);
		if (folder == null)
		{
			return;
		}

		int at = roots.indexOf(FOLDER + folderId);
		if (at < 0)
		{
			at = roots.size();
		}
		else
		{
			roots.remove(at);
		}

		for (String tag : folder.getTags())
		{
			roots.add(at++, TAG + tag);
		}
		save();
	}

	/** Root index of a row, for working out where a drop should land. */
	int rootIndexOf(StripRow row)
	{
		if (row.isFolder())
		{
			return roots.indexOf(FOLDER + row.getFolder().getId());
		}
		return roots.indexOf(TAG + row.getTag());
	}

	String rootKey(StripRow row)
	{
		return row.isFolder() ? FOLDER + row.getFolder().getId() : TAG + row.getTag();
	}

	/**
	 * Unlink a tag from wherever it currently sits.
	 * <p>
	 * Not saved on its own: every caller goes on to re-file the tag and saves
	 * once, so a half-applied move never reaches disk.
	 */
	private void detach(String tag)
	{
		roots.remove(TAG + tag);

		for (Folder folder : new ArrayList<>(folders.values()))
		{
			if (folder.getTags().remove(tag) && folder.getTags().isEmpty())
			{
				folders.remove(folder.getId());
				roots.remove(FOLDER + folder.getId());
			}
		}
	}

	private String newId()
	{
		String id;
		do
		{
			id = Long.toHexString(ThreadLocalRandom.current().nextLong() & 0xFFFFFFFFFFFFL);
		}
		while (folders.containsKey(id));
		return id;
	}
}

package com.banktagfolders;

import javax.annotation.Nullable;

/**
 * One row of the tag column: either a folder header or a tag tab.
 * <p>
 * Rows are derived fresh from {@link FolderTree} on every render and thrown
 * away afterwards. They exist so the renderer and the drag handler agree on
 * what a given widget represents without either of them re-walking the tree.
 */
class StripRow
{
	enum Kind
	{
		FOLDER,
		TAG
	}

	private final Kind kind;

	@Nullable
	private final String tag;

	@Nullable
	private final Folder folder;

	/** The folder this tag sits inside, or null when the tag is top level. */
	@Nullable
	private final Folder parent;

	private StripRow(Kind kind, @Nullable String tag, @Nullable Folder folder, @Nullable Folder parent)
	{
		this.kind = kind;
		this.tag = tag;
		this.folder = folder;
		this.parent = parent;
	}

	static StripRow folder(Folder folder)
	{
		return new StripRow(Kind.FOLDER, null, folder, null);
	}

	static StripRow tag(String tag, @Nullable Folder parent)
	{
		return new StripRow(Kind.TAG, tag, null, parent);
	}

	boolean isFolder()
	{
		return kind == Kind.FOLDER;
	}

	boolean isTag()
	{
		return kind == Kind.TAG;
	}

	/** True when this tag is nested, and so should be drawn indented. */
	boolean isNested()
	{
		return parent != null;
	}

	@Nullable
	String getTag()
	{
		return tag;
	}

	@Nullable
	Folder getFolder()
	{
		return folder;
	}

	@Nullable
	Folder getParent()
	{
		return parent;
	}

	/**
	 * Whether two rows stand for the same thing.
	 * <p>
	 * Compared by what they name rather than by identity: rows are rebuilt from
	 * scratch on every render, so two objects describing the same tab are
	 * routine.
	 */
	boolean sameAs(@Nullable StripRow other)
	{
		if (other == null || other.kind != kind)
		{
			return false;
		}
		if (kind == Kind.FOLDER)
		{
			return folder.getId().equals(other.folder.getId());
		}
		return tag.equals(other.tag);
	}
}

package com.banktagfolders;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Provider;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.FontID;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetConfig;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

/**
 * The tag column, rearranged into folders.
 * <p>
 * Bank Tags draws its own column and keeps doing so. It builds the strip as
 * dynamic children of {@code Bankmain.ITEMS_CONTAINER}: four fixed widgets (the
 * scroll catcher, the two arrows and the new-tab button) followed by a
 * background and an icon for every tab. After each of its rebuilds this class
 * hides the tabs inside closed folders, adds a header row for each folder, and
 * restacks what is left. Every tab stays Bank Tags' own widget, so renaming,
 * deleting, exporting, layouts, icons and dropping an item on a tab are still
 * its code doing it.
 * <p>
 * Core relays its tabs out by position in that child array from several places
 * that raise no event, so {@link #heal()} notices when it has done so and draws
 * again. Everything of ours is appended after core's widgets and removed again
 * before each redraw.
 */
@Slf4j
@Singleton
public class TagColumn
{
	private static final java.awt.Color HILIGHT_COLOR = JagexColors.MENU_TARGET;

	static final String SCROLL_UP = "Scroll up";
	static final String SCROLL_DOWN = "Scroll down";
	static final String OPTION_VIEW_TAG = "View tag tab";
	static final String OPTION_UNFILE = "Remove from folder";
	static final String OPTION_NEW_FOLDER = "New folder";

	private static final int TAB_WIDTH = 39;
	private static final int MARGIN = 1;
	/** Children core creates before any tab: scroll catcher, up, down, new tab. */
	private static final int CORE_BUTTONS = 4;
	/** Height core gives a tab, and the height of the sprite behind it. */
	private static final int NATIVE_TAB_HEIGHT = 40;
	private static final int MIN_ROW_HEIGHT = 24;
	/** Rate limit for hold-to-scroll on the arrow buttons, in milliseconds. */
	private static final int SCROLL_TICK = 500;
	private static final int HIDDEN = Integer.MIN_VALUE;

	/** Ours, registered on a tag's own background beside core's six. */
	static final int TAB_OP_UNFILE = 7;
	static final int NEWTAB_OP_NEW_FOLDER = 4;

	static final int FOLDER_OP_TOGGLE = 1;
	static final int FOLDER_OP_CHANGE_ICON = 2;
	static final int FOLDER_OP_SET_COLOUR = 3;
	static final int FOLDER_OP_RENAME = 4;
	static final int FOLDER_OP_DELETE = 5;

	private static final int FOLDER_TEXT = 0xFFFFFF;

	private final Client client;
	private final BankTagFoldersConfig config;
	private final FolderTree tree;
	private final CoreBankTags core;

	/**
	 * Lazily resolved to break the injection cycle: the actions ask for a redraw
	 * when they finish, and the column hands them clicks.
	 */
	private final Provider<ColumnActions> actions;

	private Widget parent;
	private Widget scroll;
	private Widget up;
	private Widget down;
	private Widget newTab;

	/** The scroll widget our listeners are on, so a fresh bank gets them again. */
	private Widget hooked;

	/** Every widget core made for a tab. */
	private final List<Widget> coreWidgets = new ArrayList<>();

	/** Widgets we added to the container, in creation order. Never core's. */
	private final List<Widget> created = new ArrayList<>();
	private final Set<Widget> ours = Collections.newSetFromMap(new IdentityHashMap<>());

	/** Where each widget should be after the last layout, or {@link #HIDDEN}. */
	private final Map<Widget, Integer> expectedY = new IdentityHashMap<>();

	private final Map<Widget, StripRow> rowByWidget = new IdentityHashMap<>();
	private final List<RenderedRow> rendered = new ArrayList<>();

	/** What the container looked like when we last drew, to notice core redrawing. */
	private Widget firstCore;
	private int childCount = -1;
	@Nullable
	private Widget lastDragged;

	private int scrollRow;
	private int availableHeight;
	private Instant startScroll = Instant.now();

	/**
	 * Set on shutdown. Rows are then drawn as core would draw them, which is what
	 * the scroll listeners we cannot hand back keep drawing until the bank is
	 * reopened and core makes its own again.
	 */
	private boolean detached;

	/** Open the folder holding the active tag on the next draw, once per bank. */
	private boolean revealPending;

	@Nullable
	private String pendingReveal;

	@Inject
	TagColumn(Client client, BankTagFoldersConfig config, FolderTree tree, CoreBankTags core,
		Provider<ColumnActions> actions)
	{
		this.client = client;
		this.config = config;
		this.tree = tree;
		this.core = core;
		this.actions = actions;
	}

	/** One widget belonging to a row, and its offset below the row's top. */
	private static class Piece
	{
		private final Widget widget;
		private final int dy;

		/** The core widget this one only mimics, hidden while that one is carried. */
		@Nullable
		private final Widget mirrorOf;

		Piece(Widget widget, int dy, @Nullable Widget mirrorOf)
		{
			this.widget = widget;
			this.dy = dy;
			this.mirrorOf = mirrorOf;
		}
	}

	private static class RenderedRow
	{
		private final StripRow row;
		private final int height;
		private final List<Piece> pieces = new ArrayList<>();

		/** Where the row last landed, or -1 while it is scrolled out of view. */
		private int top = -1;

		RenderedRow(StripRow row, int height)
		{
			this.row = row;
			this.height = height;
		}
	}

	/** What core has drawn. */
	private static final class CoreColumn
	{
		private Widget parent;
		private Widget scroll;
		private Widget up;
		private Widget down;
		private Widget newTab;

		/** Core's widgets per tab, in the order it made them: background, then icon. */
		private final Map<String, List<Widget>> tabs = new LinkedHashMap<>();
	}

	/** Where a drop landed relative to the row under the cursor. */
	enum DropZone
	{
		BEFORE,
		INTO,
		AFTER
	}

	/**
	 * A resolved drop: the row under the cursor and which part of it was hit.
	 * <p>
	 * The distinction is what lets one gesture do two jobs. Dropping into the
	 * middle of a tab groups the two into a folder, the way phone home screens
	 * do; dropping near an edge inserts between rows instead.
	 */
	static class Drop
	{
		private final StripRow row;
		private final DropZone zone;

		Drop(StripRow row, DropZone zone)
		{
			this.row = row;
			this.zone = zone;
		}

		StripRow getRow()
		{
			return row;
		}

		DropZone getZone()
		{
			return zone;
		}
	}

	// ------------------------------------------------------------------
	// Reading core's column
	// ------------------------------------------------------------------

	@Nullable
	private CoreColumn scan()
	{
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		if (container == null)
		{
			return null;
		}

		Widget[] children = container.getChildren();
		if (children == null || children.length < CORE_BUTTONS)
		{
			return null;
		}

		Widget[] buttons = Arrays.copyOf(children, CORE_BUTTONS);
		for (Widget button : buttons)
		{
			if (button == null)
			{
				return null;
			}
		}

		// Anything else in the container is not core's column: another plugin
		// may share it, and drawing into somebody else's widgets would be worse
		// than drawing nothing.
		if (!hasAction(buttons[1], SCROLL_UP) || !hasAction(buttons[2], SCROLL_DOWN))
		{
			return null;
		}

		CoreColumn column = new CoreColumn();
		column.parent = container;
		column.scroll = buttons[0];
		column.up = buttons[1];
		column.down = buttons[2];
		column.newTab = buttons[3];

		for (int i = CORE_BUTTONS; i < children.length; i++)
		{
			Widget child = children[i];
			if (child == null || ours.contains(child))
			{
				continue;
			}

			String name = child.getName();
			if (name == null || name.isEmpty())
			{
				continue;
			}

			String tag = Text.removeTags(name);
			if (!tag.isEmpty())
			{
				column.tabs.computeIfAbsent(tag, t -> new ArrayList<>(2)).add(child);
			}
		}

		return column;
	}

	/** Take away an option we added, without growing the array to say so. */
	private static void clearAction(Widget widget, int index)
	{
		String[] ops = widget.getActions();
		if (ops != null && ops.length > index && ops[index] != null)
		{
			widget.setAction(index, null);
		}
	}

	private static boolean hasAction(Widget widget, String option)
	{
		String[] ops = widget.getActions();
		if (ops == null)
		{
			return false;
		}
		for (String op : ops)
		{
			if (option.equals(op))
			{
				return true;
			}
		}
		return false;
	}

	// ------------------------------------------------------------------
	// Drawing
	// ------------------------------------------------------------------

	/**
	 * Draw the column again from core's widgets.
	 * <p>
	 * Wrapped end to end: a layout mistake should cost the player their folders
	 * for a frame, never their bank.
	 */
	void rebuild()
	{
		try
		{
			draw();
		}
		catch (Exception e)
		{
			log.warn("Tag column rebuild failed; leaving the bank alone", e);
		}
	}

	private void draw()
	{
		CoreColumn column = scan();
		if (column == null)
		{
			forget();
			return;
		}

		parent = column.parent;
		scroll = column.scroll;
		up = column.up;
		down = column.down;
		newTab = column.newTab;

		removeOurs();
		hook();

		if (detached)
		{
			clearAction(newTab, NEWTAB_OP_NEW_FOLDER);
		}
		else
		{
			newTab.setAction(NEWTAB_OP_NEW_FOLDER, OPTION_NEW_FOLDER);
		}

		// The tab list in config is what core keeps current, and it is the only
		// thing that may delete a folder entry. An empty answer while core has
		// tabs drawn means we asked mid-rebuild, and must not read as "all gone".
		List<String> live = core.tagTabs();
		if (!live.isEmpty() || column.tabs.isEmpty())
		{
			tree.reconcile(live);
		}

		if (revealPending)
		{
			revealPending = false;
			String active = core.activeTag();
			if (active != null)
			{
				// Expanded before the rows are flattened, so the tag is actually
				// among them and can be scrolled to below.
				tree.reveal(active);
				pendingReveal = active;
			}
		}

		List<StripRow> rows = detached ? flat(column) : tree.rows();
		int height = detached ? NATIVE_TAB_HEIGHT : rowHeight();

		for (List<Widget> widgets : column.tabs.values())
		{
			coreWidgets.addAll(widgets);
		}

		for (StripRow row : rows)
		{
			RenderedRow built = row.isFolder()
				? buildFolderRow(row, height, column)
				: buildTagRow(row, height, column.tabs.get(row.getTag()));
			if (built != null)
			{
				rendered.add(built);
			}
		}

		layoutRows();

		if (pendingReveal != null)
		{
			scrollToTag(pendingReveal);
			pendingReveal = null;
		}

		remember();
	}

	private static List<StripRow> flat(CoreColumn column)
	{
		List<StripRow> rows = new ArrayList<>();
		for (String tag : column.tabs.keySet())
		{
			rows.add(StripRow.tag(tag, null));
		}
		return rows;
	}

	/**
	 * Cut our widgets back off, leaving core's exactly as it made them.
	 * <p>
	 * Found by identity rather than by where they sit, and from a set that
	 * outlives {@link #forget()}. Anything of ours that is left attached but no
	 * longer tracked is never hidden or moved again, and stays on screen at its
	 * old position, painting a folder's tint over whichever tab now sits there.
	 */
	private void removeOurs()
	{
		Widget[] children = parent.getChildren();
		if (children != null && !ours.isEmpty())
		{
			List<Widget> kept = new ArrayList<>(children.length);
			for (Widget child : children)
			{
				if (child != null && !ours.contains(child))
				{
					kept.add(child);
				}
			}

			// Core may have rebuilt its tabs since, truncating the child array
			// and taking ours with it, in which case there is nothing to cut.
			if (kept.size() != children.length)
			{
				// Copied from the array the client handed over rather than built
				// fresh: it only accepts its own array type, and a plain Widget[]
				// fails with a ClassCastException on every redraw.
				Widget[] trimmed = Arrays.copyOf(children, kept.size());
				for (int i = 0; i < trimmed.length; i++)
				{
					trimmed[i] = kept.get(i);
				}
				parent.setChildren(trimmed);
			}
		}

		created.clear();
		ours.clear();
		rowByWidget.clear();
		rendered.clear();
		coreWidgets.clear();
		expectedY.clear();
	}

	/**
	 * Take over scrolling. Core scrolls by an index into its flat tab list, which
	 * is not what is drawn once folders are closed, so its arithmetic lands on the
	 * wrong row. Replacing the listeners on the widgets it already made beats
	 * adding a second set of arrows.
	 */
	private void hook()
	{
		if (scroll == hooked)
		{
			return;
		}
		hooked = scroll;

		scroll.setOnScrollWheelListener((JavaScriptCallback) event -> scrollBy(event.getMouseY()));
		up.setOnOpListener((JavaScriptCallback) event -> scrollBy(-1));
		down.setOnOpListener((JavaScriptCallback) event -> scrollBy(1));
	}

	private void remember()
	{
		Widget[] children = parent.getChildren();
		childCount = children == null ? -1 : children.length;
		firstCore = children != null && children.length > CORE_BUTTONS ? children[CORE_BUTTONS] : null;
	}

	/**
	 * Redraw if core has rebuilt or relaid its column behind our back.
	 * <p>
	 * Core rebuilds its tabs from inside its own option handlers (delete, rename,
	 * import) and relays them out when the bank is resized, none of which raises
	 * an event we hear. Both are cheap to spot: a rebuild replaces the widgets,
	 * and a relayout moves or unhides ones we have placed. Two reads per widget
	 * when there is nothing to do.
	 */
	void heal()
	{
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		if (container == null)
		{
			return;
		}

		Widget[] children = container.getChildren();
		if (children == null || children.length <= CORE_BUTTONS)
		{
			return;
		}

		if (!attached(children))
		{
			rebuild();
		}
		else if (!placed())
		{
			layoutRows();
		}
	}

	private boolean attached(Widget[] children)
	{
		if (firstCore == null || scroll == null || children.length != childCount)
		{
			return false;
		}
		if (children[0] != scroll || children[CORE_BUTTONS] != firstCore)
		{
			return false;
		}
		return created.isEmpty() || children[children.length - 1] == created.get(created.size() - 1);
	}

	private boolean placed()
	{
		Widget dragged = client.getDraggedWidget();
		if (dragged != lastDragged)
		{
			return false;
		}

		for (Map.Entry<Widget, Integer> entry : expectedY.entrySet())
		{
			Widget widget = entry.getKey();
			if (widget == dragged)
			{
				continue;
			}

			int y = entry.getValue();
			boolean hidden = widget.isSelfHidden();
			if (y == HIDDEN ? !hidden : hidden || widget.getOriginalY() != y)
			{
				return false;
			}
		}
		return true;
	}

	/** Forget everything: the bank closed, or core's column is gone. */
	void forget()
	{
		parent = scroll = up = down = newTab = hooked = null;
		firstCore = null;
		lastDragged = null;
		childCount = -1;
		// created and ours are kept: whatever of ours is still attached has to be
		// found and removed by the next draw.
		created.clear();
		rowByWidget.clear();
		rendered.clear();
		coreWidgets.clear();
		expectedY.clear();
	}

	void onBankClosed()
	{
		forget();
		scrollRow = 0;
		revealPending = false;
		pendingReveal = null;
	}

	/** Ask for the active tag's folder to be opened when the column next builds. */
	void requestReveal()
	{
		revealPending = true;
	}

	/**
	 * Put the column back as core drew it and stop interfering.
	 * <p>
	 * Core's scroll listeners were lambdas we replaced and cannot be handed back,
	 * so the column is left drawing core's flat list, which is also what they
	 * will keep drawing until the bank is reopened and core makes its own again.
	 */
	void release()
	{
		detached = true;
		rebuild();
	}

	void attach()
	{
		detached = false;
	}

	// ------------------------------------------------------------------
	// Building rows
	// ------------------------------------------------------------------

	@Nullable
	private RenderedRow buildTagRow(StripRow row, int height, @Nullable List<Widget> widgets)
	{
		if (widgets == null || widgets.isEmpty())
		{
			return null;
		}

		Widget background = widgets.get(0);
		Widget icon = widgets.size() > 1 ? widgets.get(1) : null;
		boolean tinted = row.isNested() && !detached;

		RenderedRow out = new RenderedRow(row, height);

		background.setSpriteTiling(true);
		background.setOriginalHeight(height);
		// Only the background carries menu options, as in core: the icon sits on
		// top of it and the two overlap, so options on both would be listed twice.
		if (tinted)
		{
			background.setAction(TAB_OP_UNFILE, OPTION_UNFILE);
		}
		else
		{
			clearAction(background, TAB_OP_UNFILE);
		}
		addDragOptions(background);
		out.pieces.add(new Piece(background, 0, null));
		rowByWidget.put(background, row);

		if (tinted)
		{
			// Lighter over the active tab, which would otherwise stop looking
			// active once it is tinted. Membership is shown by colour rather than
			// by indenting: the column is 39px wide and an item sprite is 36.
			boolean active = row.getTag().equals(core.activeTag());
			int opacity = Math.min(255, opacityOf(config.tagTintStrength()) + (active ? 60 : 0));
			out.pieces.add(new Piece(fill(row.getParent().getColor(), opacity, height), 0, null));
		}

		if (icon != null)
		{
			int iconDy = Math.max(0, (height - Constants.ITEM_SPRITE_HEIGHT) / 2);
			out.pieces.add(new Piece(icon, iconDy, null));
			rowByWidget.put(icon, row);

			if (tinted && icon.getItemId() > 0)
			{
				// The tint is a rectangle over core's widgets, which would wash out
				// the icon underneath. Drawn again on top, with nothing to click, so
				// the real icon below still takes the clicks and the drag.
				out.pieces.add(new Piece(item(icon.getName(), icon.getItemId(), MARGIN + 3), iconDy, icon));
			}
		}

		return out;
	}

	private RenderedRow buildFolderRow(StripRow row, int height, CoreColumn column)
	{
		Folder folder = row.getFolder();
		String name = ColorUtil.wrapWithColorTag(folder.getName(), HILIGHT_COLOR);

		RenderedRow out = new RenderedRow(row, height);

		Widget background = fill(folder.getColor(), opacityOf(config.folderTintStrength()), height);
		background.setName(name);
		background.setAction(FOLDER_OP_TOGGLE, folder.isCollapsed() ? "Expand" : "Collapse");
		background.setAction(FOLDER_OP_CHANGE_ICON, "Change icon");
		background.setAction(FOLDER_OP_SET_COLOUR, "Set colour");
		background.setAction(FOLDER_OP_RENAME, "Rename folder");
		background.setAction(FOLDER_OP_DELETE, "Delete folder");
		background.setHasListener(true);
		background.setOnOpListener((JavaScriptCallback) event ->
			actions.get().onFolderOp(event.getOp() - 1, row));
		addDragOptions(background);
		out.pieces.add(new Piece(background, 0, null));
		rowByWidget.put(background, row);

		// Item sprites are transparent around the item, so the folder's colour
		// still reads through from the rectangle behind. Drawn at its native
		// size: scaling one down is a nearest-neighbour resample and looks
		// visibly broken.
		int icon = folderIcon(folder, column);
		if (icon > 0)
		{
			Widget sprite = item(name, icon, MARGIN + 3);
			out.pieces.add(new Piece(sprite, Math.max(0, (height - Constants.ITEM_SPRITE_HEIGHT) / 2), null));
		}

		// A plain "+"/"-" rather than a chevron: the game fonts do not carry the
		// arrow codepoints, and a missing glyph reads as an empty row. Badged
		// into the corner when there is an icon under it.
		Widget marker = child(WidgetType.TEXT);
		marker.setText(folder.isCollapsed() ? "+" : "-");
		marker.setFontId(FontID.BOLD_12);
		marker.setTextColor(FOLDER_TEXT);
		marker.setTextShadowed(true);
		marker.setOriginalX(MARGIN + 2);
		marker.setOriginalWidth(10);
		marker.setOriginalHeight(icon > 0 ? 12 : height);
		marker.setXTextAlignment(WidgetTextAlignment.LEFT);
		marker.setYTextAlignment(WidgetTextAlignment.CENTER);
		marker.revalidate();
		out.pieces.add(new Piece(marker, 0, null));

		return out;
	}

	/**
	 * A folder with no icon of its own borrows its first member's, so a folder
	 * made by dragging two tabs together is never a blank bar.
	 */
	private static int folderIcon(Folder folder, CoreColumn column)
	{
		if (folder.getIconItemId() > 0)
		{
			return folder.getIconItemId();
		}

		for (String tag : folder.getTags())
		{
			List<Widget> widgets = column.tabs.get(tag);
			if (widgets != null && widgets.size() > 1 && widgets.get(1).getItemId() > 0)
			{
				return widgets.get(1).getItemId();
			}
		}
		return 0;
	}

	/**
	 * Make a widget both draggable and a drop target.
	 * <p>
	 * Core only does this to the icon. Doing it to the background too means an
	 * item dropped anywhere on a tab tags it, and the tab can be picked up by any
	 * part of it.
	 */
	private static void addDragOptions(Widget w)
	{
		w.setClickMask(w.getClickMask() | WidgetConfig.DRAG | WidgetConfig.DRAG_ON);
		w.setDragDeadTime(5);
		w.setDragDeadZone(5);
	}

	private Widget child(int type)
	{
		Widget widget = parent.createChild(-1, type);
		created.add(widget);
		ours.add(widget);
		return widget;
	}

	/** A filled rectangle in the given colour, used for folder and member tint. */
	private Widget fill(int rgb, int opacity, int height)
	{
		Widget w = child(WidgetType.RECTANGLE);
		w.setFilled(true);
		w.setTextColor(rgb);
		w.setOpacity(opacity);
		w.setOriginalX(MARGIN);
		w.setOriginalY(-1);
		w.setOriginalWidth(TAB_WIDTH);
		w.setOriginalHeight(height);
		w.revalidate();
		return w;
	}

	private Widget item(String name, int itemId, int x)
	{
		Widget w = child(WidgetType.GRAPHIC);
		w.setSpriteId(-1);
		w.setItemId(itemId);
		w.setItemQuantity(-1);
		w.setBorderType(1);
		w.setName(name);
		w.setOriginalX(x);
		w.setOriginalY(-1);
		w.setOriginalWidth(Constants.ITEM_SPRITE_WIDTH);
		w.setOriginalHeight(Constants.ITEM_SPRITE_HEIGHT);
		w.revalidate();
		return w;
	}

	/**
	 * Clamped rather than trusted. A value stored while the allowed range was
	 * wider would otherwise keep rendering out of range until someone reopened
	 * the setting.
	 */
	private int rowHeight()
	{
		return Math.max(MIN_ROW_HEIGHT, Math.min(BankTagFoldersConfig.MAX_ROW_HEIGHT, config.tagRowHeight()));
	}

	/**
	 * Config gives strength as a percentage of colour; widgets want the
	 * opposite, where 0 is solid and 255 is invisible.
	 */
	static int opacityOf(int strength)
	{
		int clamped = Math.max(0, Math.min(100, strength));
		return 255 - (clamped * 255 / 100);
	}

	// ------------------------------------------------------------------
	// Layout and scrolling
	// ------------------------------------------------------------------

	/** Position the visible window of rows; everything else is hidden. */
	void layoutRows()
	{
		if (parent == null || scroll == null)
		{
			return;
		}

		Widget dragged = client.getDraggedWidget();
		lastDragged = dragged;
		expectedY.clear();

		for (Widget widget : coreWidgets)
		{
			hide(widget, dragged);
		}
		for (Widget widget : created)
		{
			hide(widget, dragged);
		}
		for (RenderedRow row : rendered)
		{
			row.top = -1;
		}

		// Core sizes the scroll catcher to the space the column has, clamped
		// against the incinerator, the collapse button and the storage popup, and
		// puts it at the top of the column. Reading it back gives both without
		// redoing core's arithmetic.
		availableHeight = scroll.getOriginalHeight();
		clampScroll();

		int y = scroll.getOriginalY() + MARGIN;
		int used = 0;
		for (int i = scrollRow; i < rendered.size(); i++)
		{
			RenderedRow row = rendered.get(i);
			if (used + row.height > availableHeight)
			{
				break;
			}

			row.top = y;
			for (Piece piece : row.pieces)
			{
				if (piece.mirrorOf != null && piece.mirrorOf == dragged)
				{
					continue;
				}

				int top = y + piece.dy;
				piece.widget.setOriginalY(top);
				piece.widget.setHidden(false);
				piece.widget.revalidate();
				expectedY.put(piece.widget, top);
			}

			y += row.height + MARGIN;
			used += row.height + MARGIN;
		}
	}

	/**
	 * Hiding the widget being dragged makes it vanish mid-drag when the column
	 * is laid out again because of a scroll.
	 */
	private void hide(Widget widget, @Nullable Widget dragged)
	{
		expectedY.put(widget, HIDDEN);
		if (widget != dragged)
		{
			widget.setHidden(true);
		}
	}

	/**
	 * Pull the scroll position back so the column always ends up full.
	 * <p>
	 * Collapsing a folder can shorten the list under the current offset, and
	 * without this the player is left staring at a mostly empty strip with no
	 * obvious way back.
	 */
	private void clampScroll()
	{
		if (scrollRow <= 0)
		{
			scrollRow = 0;
			return;
		}

		int used = 0;
		int first = rendered.size();
		for (int i = rendered.size() - 1; i >= 0; i--)
		{
			int height = rendered.get(i).height;
			if (used + height > availableHeight)
			{
				break;
			}
			used += height + MARGIN;
			first = i;
		}
		scrollRow = Math.min(scrollRow, first);
	}

	/** Scroll a tag into view, if it did not already land on screen. */
	private void scrollToTag(String tag)
	{
		for (int i = 0; i < rendered.size(); i++)
		{
			RenderedRow row = rendered.get(i);
			if (row.row.isTag() && tag.equals(row.row.getTag()))
			{
				if (row.top < 0)
				{
					scrollRow = i;
					layoutRows();
				}
				return;
			}
		}
	}

	void scrollBy(int delta)
	{
		if (parent == null || delta == 0)
		{
			return;
		}

		int next = scrollRow + delta;
		if (next < 0)
		{
			next = 0;
		}
		if (next >= rendered.size())
		{
			next = Math.max(0, rendered.size() - 1);
		}

		scrollRow = next;
		layoutRows();
	}

	/** Rate-limited scroll, so holding a drag over an arrow does not race. */
	void scrollTick(int direction)
	{
		if (startScroll.until(Instant.now(), ChronoUnit.MILLIS) >= SCROLL_TICK)
		{
			startScroll = Instant.now();
			scrollBy(direction);
		}
	}

	// ------------------------------------------------------------------
	// Hit testing
	// ------------------------------------------------------------------

	boolean isDrawn()
	{
		return parent != null && !rendered.isEmpty();
	}

	/** The row a widget stands for, or null when it is not one of the column's rows. */
	@Nullable
	StripRow rowFor(@Nullable Widget widget)
	{
		return widget == null ? null : rowByWidget.get(widget);
	}

	/** Widgets we added, as opposed to core's. */
	boolean isOurs(@Nullable Widget widget)
	{
		return widget != null && ours.contains(widget);
	}

	/** -1 for the up arrow, 1 for the down arrow, 0 for anything else. */
	int arrowDirection(@Nullable Widget widget)
	{
		if (widget == null)
		{
			return 0;
		}
		return widget == up ? -1 : widget == down ? 1 : 0;
	}

	boolean isNewTab(@Nullable Widget widget)
	{
		return widget != null && widget == newTab;
	}

	/** Whether a point on the canvas falls inside the column. */
	boolean containsCanvasPoint(@Nullable Point point)
	{
		if (point == null || parent == null || parent.isHidden())
		{
			return false;
		}

		java.awt.Rectangle bounds = parent.getBounds();
		return point.getX() >= bounds.x
			&& point.getX() <= bounds.x + MARGIN + TAB_WIDTH
			&& point.getY() >= bounds.y
			&& point.getY() <= bounds.y + bounds.height;
	}

	/**
	 * Resolve a drop point to a row and a zone.
	 * <p>
	 * The outer quarter at each end of a row inserts beside it; the middle half
	 * drops into it. A quarter of a 40px tab is 10px, which is enough to hit
	 * deliberately without being easy to hit by accident.
	 */
	@Nullable
	Drop dropAt(@Nullable Point point)
	{
		if (point == null || parent == null)
		{
			return null;
		}

		int local = point.getY() - parent.getBounds().y;

		for (RenderedRow row : rendered)
		{
			if (row.top < 0 || local < row.top || local >= row.top + row.height)
			{
				continue;
			}

			int offset = local - row.top;
			int edge = Math.max(4, row.height / 4);
			if (offset < edge)
			{
				return new Drop(row.row, DropZone.BEFORE);
			}
			if (offset >= row.height - edge)
			{
				return new Drop(row.row, DropZone.AFTER);
			}
			return new Drop(row.row, DropZone.INTO);
		}

		// Below the last row but still inside the column: append at the end.
		return null;
	}
}

package com.banktagfolders;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Launches a dev client with the plugin loaded: {@code gradlew run}.
 */
public class BankTagFoldersPluginTest
{
	@SuppressWarnings("unchecked")
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(BankTagFoldersPlugin.class);
		RuneLite.main(args);
	}
}

package com.banktagfolders;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Turns the claims this plugin makes about itself into something the build
 * checks.
 * <p>
 * The Plugin Hub reviews two things: that a plugin is not malicious, and that
 * it stays inside Jagex's third-party client guidelines. Both are properties of
 * the source, so both can be asserted against the source. Every rule below
 * corresponds to a statement in the README; if someone later writes code that
 * contradicts one, the build fails rather than the claim quietly going stale.
 * <p>
 * Scanning is done with comments stripped, so prose explaining a rule is never
 * mistaken for a breach of it.
 */
public class ComplianceTest
{
	private static final Path SOURCE_ROOT = Paths.get("src", "main", "java");

	private Map<String, String> sources()
	{
		try (Stream<Path> files = Files.walk(SOURCE_ROOT))
		{
			Map<String, String> out = new LinkedHashMap<>();
			for (Path p : files.filter(f -> f.toString().endsWith(".java")).collect(Collectors.toList()))
			{
				out.put(p.getFileName().toString(), stripComments(
					new String(Files.readAllBytes(p), StandardCharsets.UTF_8)));
			}
			assertTrue("no sources found under " + SOURCE_ROOT, !out.isEmpty());
			return out;
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}
	}

	/** Remove block and line comments so documentation cannot trip a rule. */
	private static String stripComments(String src)
	{
		return src.replaceAll("(?s)/\\*.*?\\*/", " ").replaceAll("(?m)//.*$", " ");
	}

	private void forbid(String why, String... patterns)
	{
		List<String> hits = new ArrayList<>();
		sources().forEach((name, body) ->
		{
			for (String p : patterns)
			{
				if (body.contains(p))
				{
					hits.add(name + " contains " + p);
				}
			}
		});
		assertEquals(why + " " + hits, 0, hits.size());
	}

	// ------------------------------------------------------------------
	// Plugin Hub rules
	// ------------------------------------------------------------------

	@Test
	public void usesNoReflection()
	{
		forbid("reflection is not permitted in hub plugins",
			"java.lang.reflect", "Class.forName", "setAccessible",
			"getDeclaredField", "getDeclaredMethod", "getDeclaredConstructor",
			"MethodHandles", "TypeToken");
	}

	/**
	 * The hub rejects plugins that build their own Gson: the client's instance
	 * is injectable and carries its serialisation settings, so a private one
	 * both duplicates it and drifts from it.
	 */
	@Test
	public void usesTheClientsGson()
	{
		forbid("inject the client's Gson rather than constructing one", "new Gson(");
	}

	@Test
	public void loadsNoCodeAndSpawnsNoProcesses()
	{
		forbid("no runtime code loading, native code or external processes",
			"ProcessBuilder", "Runtime.getRuntime", "System.load", "System.loadLibrary",
			"URLClassLoader", "defineClass", "ScriptEngine");
	}

	@Test
	public void touchesNoFilesystem()
	{
		forbid("everything is stored through RuneLite's ConfigManager",
			"java.io.File", "java.nio.file", "FileInputStream", "FileOutputStream",
			"FileReader", "FileWriter", "RandomAccessFile");
	}

	/** No third-party server, which is why no data-sharing warning is needed. */
	@Test
	public void makesNoNetworkCalls()
	{
		forbid("the plugin sends no data anywhere",
			"java.net.", "HttpURLConnection", "okhttp", "OkHttp", "Socket",
			"http://", "https://");
	}

	@Test
	public void addsNoThirdPartyDependencies() throws IOException
	{
		String build = new String(Files.readAllBytes(Paths.get("build.gradle")), StandardCharsets.UTF_8);
		List<String> offenders = new ArrayList<>();
		for (String line : build.split("\n"))
		{
			String t = line.trim();
			boolean declares = t.startsWith("implementation")
				|| t.startsWith("compileOnly")
				|| t.startsWith("annotationProcessor")
				|| t.startsWith("testImplementation");
			// Anything not from RuneLite, Lombok or JUnit has to be verified by
			// hand by a maintainer before the plugin can be accepted.
			if (declares && !(t.contains("net.runelite") || t.contains("lombok") || t.contains("junit")))
			{
				offenders.add(t);
			}
		}
		assertEquals("unexpected dependency " + offenders, 0, offenders.size());
	}

	/**
	 * The README promises that nothing is written into Bank Tags' configuration
	 * and that disabling the plugin leaves the flat tag list as it was. Writing
	 * through its managers, or to its config group, would break that.
	 */
	@Test
	public void writesNothingIntoBankTags()
	{
		forbid("the plugin must not write into the Bank Tags configuration",
			"TabManager", "TagManager", "LayoutManager",
			"setConfiguration(BankTagsPlugin", "unsetConfiguration(BankTagsPlugin");
	}

	// ------------------------------------------------------------------
	// Jagex third-party client guidelines
	// ------------------------------------------------------------------

	/** No added menu entries, and no invoking existing ones programmatically. */
	@Test
	public void sendsNothingToTheServer()
	{
		forbid("the plugin must not send actions to the server",
			"createMenuEntry", "setMenuEntries", "insertMenuItem",
			"menuAction(", "invokeMenuAction");
	}

	/**
	 * Jagex protects the click zones of the 3D scene, inventory, worn equipment,
	 * spellbook and prayer book. This plugin only ever addresses the bank, so
	 * the simplest way to show it stays clear of those is to require that the
	 * bank is the only interface it names.
	 */
	@Test
	public void addressesOnlyTheBankInterface()
	{
		List<String> offenders = new ArrayList<>();
		sources().forEach((name, body) ->
		{
			Matcher m = Pattern.compile("InterfaceID\\.([A-Za-z_]+)").matcher(body);
			while (m.find())
			{
				if (!m.group(1).equalsIgnoreCase("BANKMAIN"))
				{
					offenders.add(name + " uses InterfaceID." + m.group(1));
				}
			}
		});
		assertEquals("only the bank may be addressed " + offenders, 0, offenders.size());
	}

	// ------------------------------------------------------------------
	// Threading and wiring
	// ------------------------------------------------------------------

	/**
	 * Calling into Client from an AWT thread throws, and the exception is
	 * swallowed, so the feature silently does nothing. Nothing here is reachable
	 * from AWT today; this keeps it that way.
	 */
	@Test
	public void keepsClientCallsOffAwtThreads()
	{
		List<String> offenders = new ArrayList<>();
		sources().forEach((name, body) ->
		{
			boolean awtFacing = body.contains("javax.swing")
				|| body.contains("java.awt.event")
				|| body.contains("MouseListener")
				|| body.contains("KeyListener")
				|| body.contains("HotkeyListener");
			if (awtFacing && body.contains("net.runelite.api.Client"))
			{
				offenders.add(name);
			}
		});
		assertEquals("AWT-facing classes must reach the client via ClientThread " + offenders,
			0, offenders.size());
	}

	/**
	 * State injected in more than one place has to be a singleton, or each
	 * injection point silently gets its own copy and the wiring does nothing.
	 * The plugin class is excluded: RuneLite manages its lifetime.
	 */
	@Test
	public void sharedStateIsSingleton()
	{
		List<String> offenders = new ArrayList<>();
		sources().forEach((name, body) ->
		{
			if (name.equals("BankTagFoldersPlugin.java") || !body.contains("@Inject"))
			{
				return;
			}
			if (!body.contains("@Singleton"))
			{
				offenders.add(name);
			}
		});
		assertEquals("injected collaborators must be @Singleton " + offenders, 0, offenders.size());
	}
}

package com.banktagfolders;

import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class PureLogicTest
{
	@Test
	public void aSingleSwapOfNamesIsARename()
	{
		assertArrayEquals(new String[]{"a", "d"},
			FolderTree.renamed(Arrays.asList("a", "b", "c"), Arrays.asList("b", "c", "d")));
	}

	@Test
	public void deletionsAdditionsAndReordersAreNotRenames()
	{
		assertNull(FolderTree.renamed(Arrays.asList("a", "b"), Collections.singletonList("b")));
		assertNull(FolderTree.renamed(Collections.singletonList("a"), Arrays.asList("a", "b")));
		assertNull(FolderTree.renamed(Arrays.asList("a", "b"), Arrays.asList("b", "a")));
		assertNull(FolderTree.renamed(Arrays.asList("a", "b"), Arrays.asList("c", "d")));
	}

	@Test
	public void hexColoursAcceptTheShapesTheMenuPromises()
	{
		assertEquals(Integer.valueOf(0x3A6B8B), ColumnActions.parseHexColour("3a6b8b"));
		assertEquals(Integer.valueOf(0x3A6B8B), ColumnActions.parseHexColour("#3A6B8B"));
		assertEquals(Integer.valueOf(0x33AABB), ColumnActions.parseHexColour(" #3ab "));
		assertNull(ColumnActions.parseHexColour("3a6b8"));
		assertNull(ColumnActions.parseHexColour("zzzzzz"));
		assertNull(ColumnActions.parseHexColour(null));
	}

	@Test
	public void tintStrengthMapsToWidgetOpacityAndIsClamped()
	{
		assertEquals(255, TagColumn.opacityOf(0));
		assertEquals(0, TagColumn.opacityOf(100));
		assertEquals(255, TagColumn.opacityOf(-20));
		assertEquals(0, TagColumn.opacityOf(500));
		assertEquals(255 - 35 * 255 / 100, TagColumn.opacityOf(35));
	}
}
